const plagiarismCandidates = `-- name: PlagiarismCandidates :many
SELECT DISTINCT ON (s.participation_id)
    s.id, s.participation_id, s.submitted_at, s.language, u.username, p.team_id, r.score
FROM submissions s
JOIN participations p ON p.id = s.participation_id
JOIN users u ON u.id = p.user_id
JOIN tasks t ON t.id = s.task_id
LEFT JOIN submission_results r ON r.submission_id = s.id AND r.dataset_id = t.active_dataset_id
WHERE s.task_id = $1::bigint AND p.contest_id = $2::bigint
  AND s.official AND s.invalidated_at IS NULL
ORDER BY s.participation_id,
    CASE WHEN $3::boolean THEN COALESCE(r.score, -1) ELSE 0 END DESC,
    s.submitted_at DESC, s.id DESC
`

type PlagiarismCandidatesParams struct {
	TaskID    int64 `json:"task_id"`
	ContestID int64 `json:"contest_id"`
	Best      bool  `json:"best"`
}

type PlagiarismCandidatesRow struct {
	ID              int64     `json:"id"`
	ParticipationID *int64    `json:"participation_id"`
	SubmittedAt     time.Time `json:"submitted_at"`
	Language        *string   `json:"language"`
	Username        string    `json:"username"`
	TeamID          *int64    `json:"team_id"`
	Score           *float64  `json:"score"`
}

// One submission per participation for the plagiarism report of a task:
// the latest official, valid submission or, with best, the best scored
// one (ties: the latest). Served by submissions_task_idx.
func (q *Queries) PlagiarismCandidates(ctx context.Context, arg PlagiarismCandidatesParams) ([]PlagiarismCandidatesRow, error) {
	rows, err := q.db.Query(ctx, plagiarismCandidates, arg.TaskID, arg.ContestID, arg.Best)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []PlagiarismCandidatesRow{}
	for rows.Next() {
		var i PlagiarismCandidatesRow
		if err := rows.Scan(
			&i.ID,
			&i.ParticipationID,
			&i.SubmittedAt,
			&i.Language,
			&i.Username,
			&i.TeamID,
			&i.Score,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const pruneCompilationCache = `-- name: PruneCompilationCache :execrows
DELETE FROM compilation_cache WHERE used_at < $1::timestamptz
`

// Entries not used since before @before (compilation_cache_used_idx).
func (q *Queries) PruneCompilationCache(ctx context.Context, before time.Time) (int64, error) {
	result, err := q.db.Exec(ctx, pruneCompilationCache, before)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const refreshTestcasesDone = `-- name: RefreshTestcasesDone :one
UPDATE submission_results sr
SET testcases_done = (SELECT count(*) FROM evaluations e WHERE e.submission_id = sr.submission_id AND e.dataset_id = sr.dataset_id)
WHERE sr.submission_id = $1 AND sr.dataset_id = $2
RETURNING testcases_done, testcases_total
`

type RefreshTestcasesDoneParams struct {
	SubmissionID int64 `json:"submission_id"`
	DatasetID    int64 `json:"dataset_id"`
}

type RefreshTestcasesDoneRow struct {
	TestcasesDone  int32 `json:"testcases_done"`
	TestcasesTotal int32 `json:"testcases_total"`
}

func (q *Queries) RefreshTestcasesDone(ctx context.Context, arg RefreshTestcasesDoneParams) (RefreshTestcasesDoneRow, error) {
	row := q.db.QueryRow(ctx, refreshTestcasesDone, arg.SubmissionID, arg.DatasetID)
	var i RefreshTestcasesDoneRow
	err := row.Scan(&i.TestcasesDone, &i.TestcasesTotal)
	return i, err
}

const setCompilationResult = `-- name: SetCompilationResult :one
UPDATE submission_results SET
    compilation_outcome = $3, compilation_text = $4, compilation_stdout = $5,
    compilation_stderr = $6, compilation_tries = compilation_tries + 1, compilation_time = $7,
    compilation_wall_time = $8, compilation_memory = $9, compilation_worker = $10,
    testcases_total = $11
WHERE submission_id = $1 AND dataset_id = $2 AND generation = $12::integer
RETURNING submission_id
`

type SetCompilationResultParams struct {
	SubmissionID        int64    `json:"submission_id"`
	DatasetID           int64    `json:"dataset_id"`
	CompilationOutcome  *string  `json:"compilation_outcome"`
	CompilationText     string   `json:"compilation_text"`
	CompilationStdout   string   `json:"compilation_stdout"`
	CompilationStderr   string   `json:"compilation_stderr"`
	CompilationTime     *float64 `json:"compilation_time"`
	CompilationWallTime *float64 `json:"compilation_wall_time"`
	CompilationMemory   *int64   `json:"compilation_memory"`
	CompilationWorker   *string  `json:"compilation_worker"`
	TestcasesTotal      int32    `json:"testcases_total"`
	Generation          int32    `json:"generation"`
}

// Stores a compilation outcome unless the result was invalidated meanwhile
// (generation mismatch); returns the number of updated rows.
func (q *Queries) SetCompilationResult(ctx context.Context, arg SetCompilationResultParams) (int64, error) {
	row := q.db.QueryRow(ctx, setCompilationResult,
		arg.SubmissionID,
		arg.DatasetID,
		arg.CompilationOutcome,
		arg.CompilationText,
		arg.CompilationStdout,
		arg.CompilationStderr,
		arg.CompilationTime,
		arg.CompilationWallTime,
		arg.CompilationMemory,
		arg.CompilationWorker,
		arg.TestcasesTotal,
		arg.Generation,
	)
	var submission_id int64
	err := row.Scan(&submission_id)
	return submission_id, err
}

